    # Bounding box covering Beira and Manga, Mozambique
    return ee.Geometry.Rectangle([34.77, -19.90, 34.93, -19.74], proj=None, geodesic=False)

def prepare_viirs_ic(asset, start, end, geom):
    ic = (ee.ImageCollection(asset)
          .filterDate(start, end)
          .filterBounds(geom))
    n = ic.size().getInfo()
    if n == 0:
        return None, 0, None
    # Detect an appropriate NTL band
    first = ee.Image(ic.first())
    band_names = first.bandNames().getInfo()
    candidates = [
        'Gap_Filled_DNB_BRDF-Corrected_NTL',
        'DNB_BRDF-Corrected_NTL',
        'DNB_BRDF_Corrected_NTL',
        'DNB_brdf_corrected_nighttime_lights',
        'gap_filled_dnb_brdf_corrected_ntl'
    ]
    band = None
    for b in candidates:
        if b in band_names:
            band = b
            break
    if band is None:
        # No known band found; treat as dataset/band issue.
        return None, 0, None
    ic = ic.select(band).rename('ntl')
    return ic, n, band

def get_stats_for_date(date_str, geom, scale=1000):
    start = ee.Date(date_str)
    # Try windows and datasets in order
    windows = [
        ('1d', start, start.advance(1, 'day')),
        ('±1d', start.advance(-1, 'day'), start.advance(2, 'day')),
        ('±3d', start.advance(-3, 'day'), start.advance(4, 'day')),
    ]
    assets = ['NASA/VIIRS/002/VNP46A2', 'NOAA/VIIRS/001/VNP46A2']

    chosen_ic = None
    chosen_n = 0
    chosen_window = None
    used_band_name = None

    for wlabel, s, e in windows:
        for asset in assets:
            ic, n, band = prepare_viirs_ic(asset, s, e, geom)
            if ic is not None and n > 0 and band is not None:
                chosen_ic = ic
                chosen_n = n
                chosen_window = wlabel
                used_band_name = band
                break
        if chosen_ic is not None:
            break

    if chosen_ic is None:
        return {'status': 'C1', 'n': 0, 'window': windows[-1][0]}

    img = chosen_ic.median().clip(geom)

    # Valid pixel count (unmasked)
    count_dict = img.reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom,
        scale=scale,
        maxPixels=1e9
    )
    count = count_dict.get('ntl').getInfo()

    total_dict = ee.Image.constant(1).rename('ones').reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom,
        scale=scale,
        maxPixels=1e9
    )
    total = total_dict.get('ones').getInfo()

    if (count is None) or (count == 0):
        return {'status': 'C2', 'n': chosen_n, 'window': chosen_window, 'count': count, 'total': total}

    mean_dict = img.reduceRegion(
        reducer=ee.Reducer.mean(),
        geometry=geom,
        scale=scale,
        maxPixels=1e9
    )
    mean_val = mean_dict.get('ntl').getInfo()

    if (mean_val is None):
        return {'status': 'C3', 'n': chosen_n, 'window': chosen_window, 'count': count, 'total': total}
    try:
        mv = float(mean_val)
    except Exception:
        return {'status': 'C3', 'n': chosen_n, 'window': chosen_window, 'count': count, 'total': total, 'mean': mean_val}

    if not (0.0 <= mv <= 10000.0):
        return {'status': 'C3', 'n': chosen_n, 'window': chosen_window, 'count': count, 'total': total, 'mean': mv}

    valid_pct = 100.0 * float(count) / float(total) if (total and total > 0) else None
    return {
        'status': 'OK',
        'n': int(chosen_n),
        'window': chosen_window,
        'count': int(count),
        'total': int(total),
        'valid_pct': valid_pct,
        'mean': mv,
        'band': used_band_name
    }

def main():
    try:
        try:
            ee.Initialize(project='earthsense-436113')
        except Exception:
            ee.Initialize()
        geom = beira_manga_geometry()
        dates = ['2019-03-09', '2019-03-24']
        stats = {}
        for d in dates:
