                cloud_str = f", Cloud/Invalid: {cloud_pct:.1f}%" if cloud_pct is not None else ""
                print(f"{d} Images: {s['n']} ({s['window']}), Valid px: {s['count']}/{s['total']} ({s['valid_pct']:.1f}%), Mean NTL: {s['mean']:.3f}{cloud_str}")
            else:
